//! The tool catalog: one generated JSON file, served verbatim on the wire.

use std::sync::OnceLock;

use serde::Deserialize;
use serde_json::Value;

use crate::profile::Profile;

/// Embedded catalog generated by the reference suite from the reference baseline.
const CATALOG_JSON: &str = include_str!("../data/tools.json");

/// One catalog entry: the wire-exact tool spec plus non-wire attribution.
///
/// `spec` is the tool object exactly as the reference server advertises it
/// (`name`, `description`, `inputSchema`, `outputSchema`, `annotations`); it is
/// served back verbatim, so any change here would show up in the parity tests.
#[derive(Debug, Clone, Deserialize)]
pub struct CatalogEntry {
    /// Registrar group the tool comes from (`checks`, `scan`, `sf`, `semantics`, ...).
    pub group: String,
    /// Profiles whose servers advertise this tool, sorted.
    pub profiles: Vec<String>,
    /// The tool object as emitted by the reference `tools/list`.
    pub spec: Value,
}

/// The full tool catalog with server identity.
#[derive(Debug, Clone, Deserialize)]
pub struct Catalog {
    protocol_version: String,
    server: CatalogServer,
    /// Extra handler kwargs the shared layer accepts on top of the published
    /// schemas (`tool name -> property name -> schema`), used for validation
    /// only — `tools/list` keeps serving the wire-exact `spec`.
    #[serde(default)]
    input_extensions: serde_json::Map<String, Value>,
    tools: Vec<CatalogEntry>,
}

#[derive(Debug, Clone, Deserialize)]
struct CatalogServer {
    name: String,
}

/// The embedded catalog failed to parse; this is a build-time bug in `data/tools.json`.
#[derive(Debug, thiserror::Error)]
#[error("embedded tool catalog is invalid: {0}")]
pub struct CatalogError(#[from] serde_json::Error);

impl Catalog {
    /// Parse the embedded catalog. Infallible in practice — `data/tools.json` is
    /// generated, and `test_embedded_catalog_parses` pins it.
    pub fn load() -> Result<Catalog, CatalogError> {
        Ok(serde_json::from_str(CATALOG_JSON)?)
    }

    /// Process-wide catalog served by the binary; parse once, share everywhere.
    pub fn global() -> &'static Catalog {
        static CATALOG: OnceLock<Catalog> = OnceLock::new();
        CATALOG.get_or_init(|| match Catalog::load() {
            Ok(catalog) => catalog,
            // The embedded file is compile-time data covered by tests, so this
            // arm means the generated catalog and the code diverged at build time.
            Err(error) => unreachable!("embedded catalog failed to parse: {error}"),
        })
    }

    /// Protocol version the reference server reports (also negotiated in `initialize`).
    pub fn protocol_version(&self) -> &str {
        &self.protocol_version
    }

    /// Server identity advertised in `initialize` (`"SpiderHead Tools"`).
    pub fn server_name(&self) -> &str {
        &self.server.name
    }

    /// Every tool spec, in the reference server's advertisement order.
    pub fn specs(&self) -> impl Iterator<Item = &Value> {
        self.tools.iter().map(|entry| &entry.spec)
    }

    /// Tool specs advertised under `profile`, in advertisement order.
    pub fn specs_for_profile(&self, profile: Profile) -> impl Iterator<Item = &Value> {
        let name = profile.as_str();
        self.tools
            .iter()
            .filter(move |entry| entry.profiles.iter().any(|p| p == name))
            .map(|entry| &entry.spec)
    }

    /// Names of the tools advertised under `profile`, in advertisement order.
    pub fn names_for_profile(&self, profile: Profile) -> Vec<&str> {
        self.specs_for_profile(profile)
            .filter_map(|spec| spec["name"].as_str())
            .collect()
    }

    /// The spec of one advertised tool, or `None` if this profile excludes it.
    pub fn find(&self, profile: Profile, name: &str) -> Option<&Value> {
        self.specs_for_profile(profile)
            .find(|spec| spec["name"] == name)
    }

    /// The catalog's `input_extensions` member (`tool name -> properties`).
    pub fn input_extensions(&self) -> &serde_json::Map<String, Value> {
        &self.input_extensions
    }

    /// The schema `tools/call` arguments are validated against: the tool's
    /// published `inputSchema` merged with its `input_extensions` properties.
    /// Advertised properties keep their declaration order; extension
    /// properties follow in catalog order.
    pub fn effective_input_schema(&self, spec: &Value) -> Option<Value> {
        let mut schema = spec.get("inputSchema")?.clone();
        let name = spec.get("name").and_then(Value::as_str)?;
        let Some(extra) = self.input_extensions.get(name).and_then(Value::as_object) else {
            return Some(schema);
        };
        if let Some(properties) = schema.get_mut("properties").and_then(Value::as_object_mut) {
            for (key, prop) in extra {
                properties.insert(key.clone(), prop.clone());
            }
        }
        Some(schema)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn test_embedded_catalog_parses() {
        let catalog = Catalog::load().expect("generated catalog must parse");
        assert_eq!(catalog.server_name(), "SpiderHead Tools");
        assert_eq!(catalog.protocol_version(), "2025-11-25");
    }

    // (the caption half: labels live in the JSON data, not in code)
    #[test]
    fn catalog_labels_match_profile_labels() {
        let raw: Value = serde_json::from_str(CATALOG_JSON).expect("catalog JSON");
        for profile in Profile::ALL {
            assert_eq!(
                raw["profile_labels"][profile.as_str()],
                Value::String(profile.label().to_string()),
                "label for {}",
                profile.as_str()
            );
        }
    }

    #[test]
    fn every_tool_has_output_schema_and_annotations() {
        let catalog = Catalog::global();
        for spec in catalog.specs() {
            let name = spec["name"].as_str().unwrap_or("?").to_string();
            assert!(
                spec.get("outputSchema").is_some(),
                "{name}: no outputSchema"
            );
            assert!(spec.get("annotations").is_some(), "{name}: no annotations");
            assert!(
                spec.get("inputSchema")
                    .is_some_and(|s| s["type"] == "object"),
                "{name}: inputSchema is not an object schema"
            );
        }
    }

    // (spot checks: the named tools carry the annotated side-effect class)
    #[test]
    fn named_tools_carry_their_safety_class() {
        let catalog = Catalog::global();
        let expected: &[(&str, bool, bool, bool, bool)] = &[
            // (tool, readOnlyHint, destructiveHint, idempotentHint, openWorldHint)
            ("seo_parse", true, false, true, true), // fetch
            ("seo_images_optimize", false, true, false, true), // rewrite_files_from_web
            ("seo_indexnow_submit", false, false, true, true), // submit
            ("seo_spend_report", true, false, true, false), // read_files
            // the reference suite defines its own create_files with openWorldHint=true.
            ("sf_audit_run", false, false, false, true), // sf-local create_files
        ];
        for (name, read_only, destructive, idempotent, open_world) in expected {
            let spec = catalog
                .find(Profile::Full, name)
                .unwrap_or_else(|| panic!("{name} missing from the full profile"));
            let annotations = &spec["annotations"];
            assert_eq!(annotations["readOnlyHint"], json!(*read_only), "{name}");
            assert_eq!(
                annotations["destructiveHint"],
                json!(*destructive),
                "{name}"
            );
            assert_eq!(annotations["idempotentHint"], json!(*idempotent), "{name}");
            assert_eq!(annotations["openWorldHint"], json!(*open_world), "{name}");
        }
    }

    #[test]
    fn profile_counts_match_the_reference_registry() {
        let catalog = Catalog::global();
        assert_eq!(catalog.names_for_profile(Profile::Full).len(), 254);
        assert_eq!(catalog.names_for_profile(Profile::Audit).len(), 10);
        assert_eq!(catalog.names_for_profile(Profile::Infra).len(), 11);
        assert_eq!(catalog.names_for_profile(Profile::QuickCheck).len(), 10);
        assert_eq!(catalog.names_for_profile(Profile::Router).len(), 4);
    }

    // (a client can only send what shows up in the published inputSchema)
    #[test]
    fn crawl_site_declares_sitemap_urls_and_config() {
        let catalog = Catalog::global();
        let schema = &catalog
            .find(Profile::Full, "seo_crawl_site")
            .unwrap_or_else(|| panic!("seo_crawl_site missing from the full profile"))
            ["inputSchema"];
        let properties: Vec<&str> = schema["properties"]
            .as_object()
            .expect("properties object")
            .keys()
            .map(String::as_str)
            .collect();
        for declared in ["sitemap", "urls", "config"] {
            assert!(
                properties.contains(&declared),
                "missing property {declared}"
            );
        }
        let required: Option<Vec<&str>> = schema
            .get("required")
            .and_then(|r| r.as_array())
            .map(|items| items.iter().filter_map(Value::as_str).collect());
        assert!(
            !required.unwrap_or_default().contains(&"url"),
            "url must stay optional: urls-only entry mode"
        );
    }

    // The `input_extensions` table documents handler kwargs accepted on top of
    // the published schemas; `tools/call` validation sees them, `tools/list`
    // must not.
    #[test]
    fn extension_properties_extend_the_call_schema_only() {
        let catalog = Catalog::global();
        assert!(!catalog.input_extensions().is_empty());
        for (name, extra) in catalog.input_extensions() {
            let spec = catalog
                .find(Profile::Full, name)
                .unwrap_or_else(|| panic!("{name}: extension targets a missing tool"));
            let published = spec["inputSchema"]["properties"]
                .as_object()
                .expect("published properties");
            let extra_props = extra.as_object().expect("extension properties");
            for (key, prop_schema) in extra_props {
                assert!(
                    !published.contains_key(key),
                    "{name}.{key}: extension shadows a published property"
                );
                assert!(
                    prop_schema.get("type").is_some() || prop_schema.get("anyOf").is_some(),
                    "{name}.{key}: extension property has no type or anyOf"
                );
            }
            let effective = catalog
                .effective_input_schema(spec)
                .expect("effective schema");
            let props = effective["properties"]
                .as_object()
                .expect("effective props");
            for key in extra_props.keys() {
                assert!(props.contains_key(key), "{name}.{key}: not merged");
            }
            assert_eq!(props.len(), published.len() + extra_props.len(), "{name}");
        }
    }

    #[test]
    fn effective_schema_leaves_unextended_tools_untouched() {
        let catalog = Catalog::global();
        let spec = catalog
            .find(Profile::Full, "seo_parse")
            .expect("seo_parse missing");
        assert!(
            catalog.input_extensions().get("seo_parse").is_none(),
            "test assumes seo_parse has no extensions"
        );
        let effective = catalog.effective_input_schema(spec).expect("schema");
        assert_eq!(effective, spec["inputSchema"]);
    }

    #[test]
    fn restricted_profiles_are_subsets_of_full_in_registration_order() {
        let catalog = Catalog::global();
        for profile in Profile::ALL {
            if profile == Profile::Full {
                continue;
            }
            let advertised = catalog.names_for_profile(profile);
            let full = catalog.names_for_profile(Profile::Full);
            assert!(
                advertised.len() < full.len(),
                "{profile} must advertise fewer tools than full"
            );
            let positions: Vec<usize> = full
                .iter()
                .enumerate()
                .filter(|(_, name)| advertised.contains(name))
                .map(|(position, _)| position)
                .collect();
            assert_eq!(positions.len(), advertised.len(), "{profile} coverage");
            assert!(
                positions.windows(2).all(|pair| pair[0] < pair[1]),
                "{profile} must keep the full profile's relative order"
            );
        }
    }
}
